def answers():
    cs = {"A": (1, 1), "B": (4, 5), "C": (8, 2)}
    out = []
    for x, y in [(2, 2), (5, 4), (7, 3)]:
        ds = {k: (x - a) ** 2 + (y - b) ** 2 for k, (a, b) in cs.items()}
        out += list(ds.values()) + [min(ds, key=ds.get)]
    return out
